:root {
  --accent: #4B3BFF;
  --accent-soft: rgba(75, 59, 255, 0.10);
  --accent-ink: #FFFFFF;
  --radius: 14px;
  --bg: #FBFAF8;
  --surface: #FFFFFF;
  --text: #16161A;
  --text-secondary: #6E6E78;
  --border: #E9E7E2;
  --danger: #E04040;
  --success: #2E9E5A;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.6;
  color: var(--text);
  background: var(--bg);
  min-height: 100vh;
}

.app {
  max-width: 760px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}

/* Header */
.header {
  margin-bottom: 32px;
}

.logo {
  font-size: 24px;
  font-weight: 680;
  margin-bottom: 16px;
  color: var(--text);
}

.summary {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.summary-item {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.summary-label {
  font-size: 13px;
  color: var(--text-secondary);
}

.summary-value {
  font-size: 18px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.summary-value.income { color: var(--success); }
.summary-value.expense { color: var(--danger); }
.summary-value.balance { color: var(--accent); }

/* Form */
.form-section {
  margin-bottom: 32px;
}

.record-form {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: 0 1px 2px rgba(0,0,0,0.04), 0 8px 24px rgba(0,0,0,0.03);
}

.form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin-bottom: 16px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field.full {
  margin-bottom: 16px;
}

.field label {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
}

.field input,
.field select {
  height: 40px;
  padding: 0 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  font-size: 15px;
  font-family: inherit;
  color: var(--text);
  background: var(--bg);
  transition: border-color 0.2s, box-shadow 0.2s;
  outline: none;
}

.field input:focus,
.field select:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.field input.invalid,
.field select.invalid {
  border-color: var(--danger);
}

.field-error {
  font-size: 12px;
  color: var(--danger);
  min-height: 16px;
}

/* Type Toggle */
.type-toggle {
  display: flex;
  border: 1px solid var(--border);
  border-radius: 8px;
  overflow: hidden;
}

.toggle-btn {
  flex: 1;
  height: 40px;
  border: none;
  background: var(--bg);
  font-size: 14px;
  font-family: inherit;
  font-weight: 500;
  color: var(--text-secondary);
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}

.toggle-btn.active {
  background: var(--accent);
  color: var(--accent-ink);
}

/* Buttons */
.btn-primary {
  width: 100%;
  height: 44px;
  border: none;
  border-radius: var(--radius);
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 15px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: opacity 0.2s, transform 0.1s;
}

.btn-primary:hover {
  opacity: 0.9;
}

.btn-primary:active {
  transform: scale(0.98);
}

/* List */
.list-section {
  margin-top: 8px;
}

.list-header {
  display: flex;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 16px;
}

.list-header h2 {
  font-size: 18px;
  font-weight: 600;
}

.record-count {
  font-size: 13px;
  color: var(--text-secondary);
}

.empty-state {
  text-align: center;
  padding: 48px 24px;
  color: var(--text-secondary);
  font-size: 14px;
}

.record-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Record Item */
.record-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px 16px;
  transition: box-shadow 0.2s;
}

.record-item:hover {
  box-shadow: 0 1px 2px rgba(0,0,0,0.04), 0 8px 24px rgba(0,0,0,0.04);
}

.record-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}

.record-icon.expense {
  background: rgba(224, 64, 64, 0.08);
}

.record-icon.income {
  background: rgba(46, 158, 90, 0.08);
}

.record-info {
  flex: 1;
  min-width: 0;
}

.record-category {
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
}

.record-note {
  font-size: 12px;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.record-right {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.record-amount {
  font-size: 15px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.record-amount.expense { color: var(--danger); }
.record-amount.income { color: var(--success); }

.record-date {
  font-size: 12px;
  color: var(--text-secondary);
}

.btn-delete {
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--text-secondary);
  font-size: 16px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s, color 0.2s;
}

.btn-delete:hover {
  background: rgba(224, 64, 64, 0.08);
  color: var(--danger);
}

/* Toast */
.toast {
  position: fixed;
  bottom: 32px;
  left: 50%;
  transform: translateX(-50%) translateY(80px);
  background: var(--text);
  color: var(--surface);
  padding: 12px 24px;
  border-radius: var(--radius);
  font-size: 14px;
  opacity: 0;
  transition: transform 0.3s, opacity 0.3s;
  pointer-events: none;
  z-index: 100;
}

.toast.show {
  transform: translateX(-50%) translateY(0);
  opacity: 1;
}

/* Responsive */
@media (max-width: 560px) {
  .form-row {
    grid-template-columns: 1fr;
  }

  .summary {
    grid-template-columns: 1fr;
    gap: 8px;
  }

  .summary-item {
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
  }

  .record-date {
    display: none;
  }

  .btn-primary {
    height: 48px;
  }

  .logo {
    font-size: 20px;
  }
}

(function () {
  'use strict';

  var STORAGE_KEY = 'nucleus:ledger-records';

  var categories = {
    expense: [
      { value: 'food', label: '餐饮', icon: '🍜' },
      { value: 'transport', label: '交通', icon: '🚌' },
      { value: 'shopping', label: '购物', icon: '🛍️' },
      { value: 'housing', label: '居住', icon: '🏠' },
      { value: 'entertainment', label: '娱乐', icon: '🎬' },
      { value: 'medical', label: '医疗', icon: '💊' },
      { value: 'education', label: '教育', icon: '📚' },
      { value: 'other_expense', label: '其他', icon: '📦' }
    ],
    income: [
      { value: 'salary', label: '工资', icon: '💰' },
      { value: 'parttime', label: '兼职', icon: '⏰' },
      { value: 'investment', label: '投资', icon: '📈' },
      { value: 'other_income', label: '其他', icon: '🎁' }
    ]
  };

  var state = {
    records: [],
    type: 'expense'
  };

  // DOM refs
  var form = document.getElementById('recordForm');
  var amountInput = document.getElementById('amount');
  var categorySelect = document.getElementById('category');
  var dateInput = document.getElementById('date');
  var noteInput = document.getElementById('note');
  var recordList = document.getElementById('recordList');
  var emptyState = document.getElementById('emptyState');
  var recordCount = document.getElementById('recordCount');
  var totalIncome = document.getElementById('totalIncome');
  var totalExpense = document.getElementById('totalExpense');
  var totalBalance = document.getElementById('totalBalance');
  var toast = document.getElementById('toast');
  var amountError = document.getElementById('amountError');
  var categoryError = document.getElementById('categoryError');
  var toggleBtns = document.querySelectorAll('.toggle-btn');

  // Init
  function init() {
    loadRecords();
    setDefaultDate();
    updateCategories();
    render();
    bindEvents();
  }

  function loadRecords() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      state.records = raw ? JSON.parse(raw) : [];
    } catch (e) {
      state.records = [];
    }
  }

  function saveRecords() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state.records));
  }

  function setDefaultDate() {
    var today = new Date();
    dateInput.value = formatDate(today);
  }

  function formatDate(d) {
    var y = d.getFullYear();
    var m = String(d.getMonth() + 1).padStart(2, '0');
    var day = String(d.getDate()).padStart(2, '0');
    return y + '-' + m + '-' + day;
  }

  function updateCategories() {
    var list = categories[state.type];
    categorySelect.innerHTML = '<option value="">请选择分类</option>';
    list.forEach(function (cat) {
      var opt = document.createElement('option');
      opt.value = cat.value;
      opt.textContent = cat.icon + ' ' + cat.label;
      categorySelect.appendChild(opt);
    });
  }

  function bindEvents() {
    // Type toggle
    toggleBtns.forEach(function (btn) {
      btn.addEventListener('click', function () {
        toggleBtns.forEach(function (b) {
          b.classList.remove('active');
          b.setAttribute('aria-checked', 'false');
        });
        btn.classList.add('active');
        btn.setAttribute('aria-checked', 'true');
        state.type = btn.dataset.type;
        updateCategories();
      });
    });

    // Form submit
    form.addEventListener('submit', function (e) {
      e.preventDefault();
      if (!validate()) return;
      addRecord();
    });

    // Delete
    recordList.addEventListener('click', function (e) {
      var btn = e.target.closest('.btn-delete');
      if (!btn) return;
      var id = btn.dataset.id;
      deleteRecord(id);
    });
  }

  function validate() {
    var valid = true;
    clearErrors();

    var amount = parseFloat(amountInput.value);
    if (!amountInput.value || isNaN(amount) || amount <= 0) {
      showError(amountInput, amountError, '请输入有效金额');
      valid = false;
    }

    if (!categorySelect.value) {
      showError(categorySelect, categoryError, '请选择分类');
      valid = false;
    }

    return valid;
  }

  function showError(input, errorEl, msg) {
    input.classList.add('invalid');
    errorEl.textContent = msg;
  }

  function clearErrors() {
    amountInput.classList.remove('invalid');
    categorySelect.classList.remove('invalid');
    amountError.textContent = '';
    categoryError.textContent = '';
  }

  function addRecord() {
    var record = {
      id: Date.now().toString(36) + Math.random().toString(36).substr(2, 5),
      type: state.type,
      amount: parseFloat(amountInput.value),
      category: categorySelect.value,
      date: dateInput.value,
      note: noteInput.value.trim(),
      createdAt: Date.now()
    };

    state.records.unshift(record);
    saveRecords();
    render();
    form.reset();
    setDefaultDate();
    showToast('已记录 ✓');
  }

  function deleteRecord(id) {
    state.records = state.records.filter(function (r) { return r.id !== id; });
    saveRecords();
    render();
    showToast('已删除');
  }

  function render() {
    renderSummary();
    renderList();
  }

  function renderSummary() {
    var now = new Date();
    var currentMonth = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');

    var income = 0, expense = 0;
    state.records.forEach(function (r) {
      if (r.date && r.date.substring(0, 7) === currentMonth) {
        if (r.type === 'income') income += r.amount;
        else expense += r.amount;
      }
    });

    totalIncome.textContent = '¥' + formatMoney(income);
    totalExpense.textContent = '¥' + formatMoney(expense);
    totalBalance.textContent = '¥' + formatMoney(income - expense);
  }

  function formatMoney(n) {
    return n.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }

  function renderList() {
    if (state.records.length === 0) {
      emptyState.style.display = 'block';
      recordList.style.display = 'none';
      recordCount.textContent = '共 0 条';
      return;
    }

    emptyState.style.display = 'none';
    recordList.style.display = 'flex';
    recordCount.textContent = '共 ' + state.records.length + ' 条';

    recordList.innerHTML = '';
    state.records.forEach(function (r) {
      var el = createRecordElement(r);
      recordList.appendChild(el);
    });
  }

  function createRecordElement(record) {
    var catInfo = findCategory(record.type, record.category);
    var div = document.createElement('div');
    div.className = 'record-item';

    var sign = record.type === 'expense' ? '-' : '+';
    var amountText = sign + '¥' + formatMoney(record.amount);

    div.innerHTML =
      '<div class="record-icon ' + escapeHtml(record.type) + '">' + escapeHtml(catInfo.icon) + '</div>' +
      '<div class="record-info">' +
        '<div class="record-category">' + escapeHtml(catInfo.label) + '</div>' +
        (record.note ? '<div class="record-note">' + escapeHtml(record.note) + '</div>' : '') +
      '</div>' +
      '<div class="record-right">' +
        '<span class="record-date">' + escapeHtml(formatDateDisplay(record.date)) + '</span>' +
        '<span class="record-amount ' + escapeHtml(record.type) + '">' + amountText + '</span>' +
        '<button type="button" class="btn-delete" data-id="' + escapeHtml(record.id) + '" aria-label="删除此记录">×</button>' +
      '</div>';

    return div;
  }

  function findCategory(type, value) {
    var list = categories[type] || [];
    for (var i = 0; i < list.length; i++) {
      if (list[i].value === value) return list[i];
    }
    return { label: '未知', icon: '❓' };
  }

  function formatDateDisplay(dateStr) {
    if (!dateStr) return '';
    var parts = dateStr.split('-');
    return parts[1] + '/' + parts[2];
  }

  function escapeHtml(str) {
    if (!str) return '';
    var map = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
    return String(str).replace(/[&<>"']/g, function (c) { return map[c]; });
  }

  var toastTimer = null;
  function showToast(msg) {
    toast.textContent = msg;
    toast.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () {
      toast.classList.remove('show');
    }, 2000);
  }

  init();
})();
